diff --git a/src/controllers/well-known.js b/src/controllers/well-known.js
new file mode 100644
index 0000000000..095266f50d
--- /dev/null
+++ b/src/controllers/well-known.js
@@ -0,0 +1,75 @@
+'use strict';
+
+const nconf = require('nconf');
+const user = require('../user');
+const privileges = require('../privileges');
+
+const wellKnownController = module.exports;
+
+wellKnownController.webfinger = async function (req, res, next) {
+	try {
+		const resource = req.query.resource;
+
+		// Validate that resource parameter is present
+		if (!resource) {
+			return res.status(400).json({ error: 'missing_resource' });
+		}
+
+		// Parse the resource parameter - must be acct:username@hostname format
+		const acctMatch = resource.match(/^acct:(.+)@(.+)$/);
+		if (!acctMatch) {
+			return res.status(400).json({ error: 'invalid_resource' });
+		}
+
+		const username = acctMatch[1];
+		const hostname = acctMatch[2];
+		const expectedHostname = nconf.get('url_parsed').hostname;
+
+		// Verify the hostname matches
+		if (hostname !== expectedHostname) {
+			return res.status(400).json({ error: 'invalid_resource' });
+		}
+
+		// Check if the current user has permission to view users
+		const canViewUsers = await privileges.global.can('view:users', req.uid);
+		if (!canViewUsers) {
+			return res.status(403).json({ error: 'no_privileges' });
+		}
+
+		// Look up the user by username
+		const uid = await user.getUidByUsername(username);
+		if (!uid) {
+			return res.status(404).json({ error: 'user_not_found' });
+		}
+
+		// Get the user data (basic info)
+		const userData = await user.getUserData(uid);
+		if (!userData) {
+			return res.status(404).json({ error: 'user_not_found' });
+		}
+
+		// Construct the webfinger response
+		const baseUrl = nconf.get('url');
+		const userslug = userData.userslug;
+		const userProfileUrl = `${baseUrl}/user/${userslug}`;
+
+		const webfingerResponse = {
+			subject: `acct:${username}@${expectedHostname}`,
+			aliases: [
+				userProfileUrl,
+			],
+			links: [
+				{
+					rel: 'http://webfinger.net/rel/profile-page',
+					href: userProfileUrl,
+				},
+			],
+		};
+
+		res.status(200).json(webfingerResponse);
+	} catch (err) {
+		next(err);
+	}
+};
+
+require('../promisify')(wellKnownController, ['webfinger']);
