+'use strict';
+
+module.exports = function (router, middleware, controllers) {
+	// WebFinger endpoint for federated identity discovery
+	router.get('/.well-known/webfinger', controllers['well-known'].webfinger);
+
+	// Redirect for password change endpoints
+	router.use('/.well-known/change-password', (req, res) => {
+		res.redirect('/me/edit/password');
+	});
+};

