+	if (!code) {
+		return false;
+	}
+
 	if (email) {
 		const confirmObj = await db.getObject(`confirm:${code}`);
 		return !!(confirmObj && email === confirmObj.email);
 	}

-	return !!code;
+	// When no email is specified, check if the confirmation object actually exists
+	const confirmObj = await db.getObject(`confirm:${code}`);
