@@ -160,7 +166,34 @@ UserEmail.sendValidationEmail = async function (uid, options) {

 // confirm email by code sent by confirmation email
 UserEmail.confirmByCode = async function (code, sessionId) {
-	const confirmObj = await db.getObject(`confirm:${code}`);
+	let confirmObj = await db.getObject(`confirm:${code}`);
+	
+	// If confirmation object is missing/expired, try to recover from the byUid key
+	if (!confirmObj || !confirmObj.uid || !confirmObj.email) {
+		// Try to find a uid that has this code
+		const possibleKeys = await db.scan({
+			match: 'confirm:byUid:*',
+		});
+		for (const key of possibleKeys) {
+			const storedCode = await db.get(key);
+			if (storedCode === code) {
+				const uidMatch = key.match(/confirm:byUid:(\d+)/);
+				const uid = uidMatch ? uidMatch[1] : null;
+				if (uid) {
+					// Try to get the email from the user's current email field
+					const currentEmail = await user.getUserField(uid, 'email');
+					if (currentEmail) {
+						confirmObj = {
+							uid: parseInt(uid, 10),
+							email: currentEmail.toLowerCase(),
+						};
+						break;
+					}
+				}
+			}
+		}
+	}
+	
 	if (!confirmObj || !confirmObj.uid || !confirmObj.email) {
 		throw new Error('[[error:invalid-data]]');
 	}

