diff --git a/src/upgrades/4.4.0/migrate_chat_list.js b/src/upgrades/4.4.0/migrate_chat_list.js
new file mode 100644
index 0000000..1404567
--- /dev/null
+++ b/src/upgrades/4.4.0/migrate_chat_list.js
@@ -0,0 +1,35 @@
+'use strict';
+
+const db = require('../../database');
+const user = require('../../user');
+
+module.exports = {
+	name: 'Migrate restrictChat to chat allow/deny lists',
+	timestamp: Date.UTC(2024, 0, 1),
+	method: async () => {
+		// Get all users that have restrictChat enabled
+		const adminCount = await db.getObjectField('global', 'userCount');
+		const users = [];
+		
+		// Get all user objects with restrictChat setting
+		for (let uid = 1; uid <= adminCount; uid++) {
+			const restrictChat = await db.getObjectField(`user:${uid}:settings`, 'restrictChat');
+			if (restrictChat === '1' || restrictChat === 1) {
+				users.push(uid);
+			}
+		}
+
+		// For each user with restrictChat enabled, migrate to allow list
+		for (const uid of users) {
+			try {
+				// Get the user's follow list
+				const followedUids = await db.getSortedSetMembers(`following:${uid}`);
+				
+				// Save as chatAllowList in JSON format
+				const chatAllowListJson = JSON.stringify(followedUids.map(id => parseInt(id, 10)));
+				await db.setObjectField(`user:${uid}:settings`, 'chatAllowList', chatAllowListJson);
+				
+				// Keep disableIncomingChats as 0 since restrictChat=1 means allow followers
+				await db.setObjectField(`user:${uid}:settings`, 'disableIncomingChats', '0');
+			} catch (err) {
+				// Silently continue if there's an issue with one user
+				console.error(`Error migrating user ${uid}:`, err.message);
+			}
+		}
+	},
+};

diff --git a/src/DirectedGraph.js b/src/DirectedGraph.js
new file mode 100644
index 0000000000..37d47de4d2
--- /dev/null
+++ b/src/DirectedGraph.js
@@ -0,0 +1,333 @@
+'use strict';
+
+/**
+ * DirectedGraph - A dedicated class for managing directed graph operations
+ * Handles vertices, arcs, component identification, and related graph statistics
+ */
+class DirectedGraph {
+	constructor() {
+		this.vertices = new Map(); // Map<string, {label?: string}>
+		this.arcs = []; // Array<{from: string, to: string}>
+		this.adjacencyList = new Map(); // Map<string, Set<string>> for efficient lookup
+		this.components = []; // Array of Sets, each Set contains vertices in a component
+		this.componentMap = new Map(); // Map<string, number> vertex -> component index
+		this.isDirty = true; // Track if components need recalculation
+	}
+
+	/**
+	 * Add a vertex to the graph
+	 * @param {string} vertexId - The unique identifier for the vertex
+	 * @param {string} [label] - Optional label for the vertex
+	 */
+	addVertex(vertexId, label) {
+		if (!this.vertices.has(vertexId)) {
+			this.vertices.set(vertexId, { label });
+			if (!this.adjacencyList.has(vertexId)) {
+				this.adjacencyList.set(vertexId, new Set());
+			}
+			this.isDirty = true;
+		} else if (label !== undefined) {
+			// Update label if provided
+			this.vertices.get(vertexId).label = label;
+		}
+	}
+
+	/**
+	 * Add an arc (directed edge) between two vertices
+	 * Creates vertices if they don't exist
+	 * @param {string} fromVertexId - Source vertex
+	 * @param {string} toVertexId - Target vertex
+	 */
+	addArc(fromVertexId, toVertexId) {
+		// Ensure vertices exist
+		this.addVertex(fromVertexId);
+		this.addVertex(toVertexId);
+
+		// Check if arc already exists
+		if (!this.adjacencyList.get(fromVertexId).has(toVertexId)) {
+			this.adjacencyList.get(fromVertexId).add(toVertexId);
+			this.arcs.push({ from: fromVertexId, to: toVertexId });
+			this.isDirty = true;
+		}
+	}
+
+	/**
+	 * Set or update a label for a vertex
+	 * @param {string} vertexId - The vertex to label
+	 * @param {string} label - The label to set
+	 */
+	setVertexLabel(vertexId, label) {
+		this.addVertex(vertexId, label);
+	}
+
+	/**
+	 * Get the label of a vertex
+	 * @param {string} vertexId - The vertex to get the label for
+	 * @returns {string|undefined} The label or undefined
+	 */
+	getVertexLabel(vertexId) {
+		const vertex = this.vertices.get(vertexId);
+		return vertex ? vertex.label : undefined;
+	}
+
+	/**
+	 * Identify connected components using DFS on the undirected version of the graph
+	 * (treating the graph as undirected for component analysis)
+	 * @private
+	 */
+	identifyComponents() {
+		this.components = [];
+		this.componentMap.clear();
+
+		const visited = new Set();
+
+		const dfs = (vertexId, component) => {
+			visited.add(vertexId);
+			component.add(vertexId);
+
+			// Visit neighbors (both outgoing and incoming edges for undirected components)
+			if (this.adjacencyList.has(vertexId)) {
+				for (const neighbor of this.adjacencyList.get(vertexId)) {
+					if (!visited.has(neighbor)) {
+						dfs(neighbor, component);
+					}
+				}
+			}
+
+			// Also visit vertices that point to this one (reverse edges)
+			for (const [source, targets] of this.adjacencyList.entries()) {
+				if (targets.has(vertexId) && !visited.has(source)) {
+					dfs(source, component);
+				}
+			}
+		};
+
+		for (const vertexId of this.vertices.keys()) {
+			if (!visited.has(vertexId)) {
+				const component = new Set();
+				dfs(vertexId, component);
+				const componentIndex = this.components.length;
+				this.components.push(component);
+
+				// Map each vertex to its component index
+				for (const vertex of component) {
+					this.componentMap.set(vertex, componentIndex);
+				}
+			}
+		}
+
+		this.isDirty = false;
+	}
+
+	/**
+	 * Ensure components are up to date
+	 * @private
+	 */
+	ensureComponentsUpdated() {
+		if (this.isDirty) {
+			this.identifyComponents();
+		}
+	}
+
+	/**
+	 * Get all vertices
+	 * @returns {string[]} Array of vertex IDs
+	 */
+	getVertices() {
+		return Array.from(this.vertices.keys());
+	}
+
+	/**
+	 * Get all arcs
+	 * @returns {Array<{from: string, to: string}>} Array of arc objects
+	 */
+	getArcs() {
+		return [...this.arcs];
+	}
+
+	/**
+	 * Check if a vertex is isolated (not connected to any other vertex)
+	 * @param {string} vertexId - The vertex to check
+	 * @returns {boolean} True if the vertex is isolated
+	 */
+	isIsolate(vertexId) {
+		if (!this.vertices.has(vertexId)) {
+			return false;
+		}
+
+		// Check if vertex has any outgoing arcs
+		if (this.adjacencyList.get(vertexId).size > 0) {
+			return false;
+		}
+
+		// Check if vertex has any incoming arcs
+		for (const targets of this.adjacencyList.values()) {
+			if (targets.has(vertexId)) {
+				return false;
+			}
+		}
+
+		return true;
+	}
+
+	/**
+	 * Get all isolates (vertices with no connections)
+	 * @returns {string[]} Array of isolated vertex IDs
+	 */
+	getIsolates() {
+		return this.getVertices().filter(vertexId => this.isIsolate(vertexId));
+	}
+
+	/**
+	 * Get the component containing a specific vertex
+	 * @param {string} vertexId - The vertex to find the component for
+	 * @returns {Set<string>|null} Set of vertices in the same component or null
+	 */
+	getComponent(vertexId) {
+		this.ensureComponentsUpdated();
+		const componentIndex = this.componentMap.get(vertexId);
+		return componentIndex !== undefined ? this.components[componentIndex] : null;
+	}
+
+	/**
+	 * Get all components
+	 * @returns {Array<Set<string>>} Array of component sets
+	 */
+	getComponents() {
+		this.ensureComponentsUpdated();
+		return [...this.components];
+	}
+
+	/**
+	 * Get statistics about the graph
+	 * @returns {Object} Statistics object
+	 */
+	getStatistics() {
+		this.ensureComponentsUpdated();
+		const isolates = this.getIsolates();
+		return {
+			vertexCount: this.vertices.size,
+			arcCount: this.arcs.length,
+			componentCount: this.components.length,
+			isolateCount: isolates.length,
+			isolates: isolates,
+		};
+	}
+
+	/**
+	 * Export graph data in a format suitable for visualization tools
+	 * @returns {Object} Graph data with nodes and links
+	 */
+	toVisualizationFormat() {
+		this.ensureComponentsUpdated();
+
+		const nodes = this.getVertices().map(vertexId => ({
+			id: vertexId,
+			label: this.getVertexLabel(vertexId) || vertexId,
+			componentIndex: this.componentMap.get(vertexId),
+			isIsolate: this.isIsolate(vertexId),
+		}));
+
+		const links = this.getArcs().map(arc => ({
+			source: arc.from,
+			target: arc.to,
+		}));
+
+		const stats = this.getStatistics();
+
+		return {
+			nodes,
+			links,
+			stats,
+			components: this.components.map(component => Array.from(component)),
+		};
+	}
+
+	/**
+	 * Clear the entire graph
+	 */
+	clear() {
+		this.vertices.clear();
+		this.arcs = [];
+		this.adjacencyList.clear();
+		this.components = [];
+		this.componentMap.clear();
+		this.isDirty = true;
+	}
+
+	/**
+	 * Get the number of vertices
+	 * @returns {number} Number of vertices
+	 */
+	getVertexCount() {
+		return this.vertices.size;
+	}
+
+	/**
+	 * Get the number of arcs
+	 * @returns {number} Number of arcs
+	 */
+	getArcCount() {
+		return this.arcs.length;
+	}
+
+	/**
+	 * Get the number of components
+	 * @returns {number} Number of connected components
+	 */
+	getComponentCount() {
+		this.ensureComponentsUpdated();
+		return this.components.length;
+	}
+
+	/**
+	 * Check if a vertex exists in the graph
+	 * @param {string} vertexId - The vertex ID to check
+	 * @returns {boolean} True if the vertex exists
+	 */
+	hasVertex(vertexId) {
+		return this.vertices.has(vertexId);
+	}
+
+	/**
+	 * Check if an arc exists in the graph
+	 * @param {string} fromVertexId - Source vertex
+	 * @param {string} toVertexId - Target vertex
+	 * @returns {boolean} True if the arc exists
+	 */
+	hasArc(fromVertexId, toVertexId) {
+		if (!this.adjacencyList.has(fromVertexId)) {
+			return false;
+		}
+		return this.adjacencyList.get(fromVertexId).has(toVertexId);
+	}
+
+	/**
+	 * Get outgoing neighbors of a vertex (vertices it points to)
+	 * @param {string} vertexId - The source vertex
+	 * @returns {string[]} Array of target vertex IDs
+	 */
+	getOutgoingNeighbors(vertexId) {
+		if (!this.adjacencyList.has(vertexId)) {
+			return [];
+		}
+		return Array.from(this.adjacencyList.get(vertexId));
+	}
+
+	/**
+	 * Get incoming neighbors of a vertex (vertices pointing to it)
+	 * @param {string} vertexId - The target vertex
+	 * @returns {string[]} Array of source vertex IDs
+	 */
+	getIncomingNeighbors(vertexId) {
+		const incoming = [];
+		for (const [source, targets] of this.adjacencyList.entries()) {
+			if (targets.has(vertexId)) {
+				incoming.push(source);
+			}
+		}
+		return incoming;
+	}
+}
+
+module.exports = DirectedGraph;

