diff --git a/src/posts/backlinks.js b/src/posts/backlinks.js
new file mode 100644
index 0000000000..1234567890
--- /dev/null
+++ b/src/posts/backlinks.js
@@ -0,0 +1,224 @@
+'use strict';
+
+const nconf = require('nconf');
+const url = require('url');
+const db = require('../database');
+const meta = require('../meta');
+const topics = require('../topics');
+
+module.exports = function (Posts) {
+	/**
+	 * Extract topic IDs from post content by looking for links to local topics
+	 * @param {string} content - HTML content to parse
+	 * @returns {array} Array of topic IDs found in the content
+	 */
+	Posts.extractTopicReferences = function (content) {
+		if (!content) {
+			return [];
+		}
+
+		const baseUrl = nconf.get('base_url');
+		const relativePath = nconf.get('relative_path');
+		const topicPattern = /href=["']([^"']+)["']/g;
+		const referencedTopics = [];
+
+		let match;
+		while ((match = topicPattern.exec(content)) !== null) {
+			const href = match[1];
+			if (!href) {
+				continue;
+			}
+
+			let topicId = null;
+
+			// Check for internal links
+			if (href.startsWith('/')) {
+				// Relative URL like /topic/123/title
+				const pathMatch = href.match(/^\/t(?:opic)?\/(\d+)/);
+				if (pathMatch) {
+					topicId = parseInt(pathMatch[1], 10);
+				}
+			} else if (href.startsWith('http')) {
+				// Absolute URL
+				try {
+					const urlObj = new url.URL(href);
+					const urlPath = urlObj.pathname;
+
+					// Check if it's the same server
+					const isSameSite = urlObj.origin === baseUrl.replace(/\/$/, '');
+					if (isSameSite || urlPath.includes(relativePath || '')) {
+						const pathMatch = urlPath.match(/\/t(?:opic)?\/(\d+)/);
+						if (pathMatch) {
+							topicId = parseInt(pathMatch[1], 10);
+						}
+					}
+				} catch (err) {
+					// Invalid URL, skip
+				}
+			}
+
+			if (topicId && !referencedTopics.includes(topicId)) {
+				referencedTopics.push(topicId);
+			}
+		}
+
+		return referencedTopics;
+	};
+
+	/**
+	 * Create backlinks for a post to all referenced topics
+	 * @param {object} postData - The post data
+	 */
+	Posts.createBacklinks = async function (postData) {
+		// Check if feature is enabled
+		if (!meta.config.enableTopicBacklinks) {
+			return;
+		}
+
+		const { pid, tid, uid, content } = postData;
+
+		// Extract referenced topic IDs from content
+		const referencedTopics = Posts.extractTopicReferences(content);
+
+		if (!referencedTopics.length) {
+			return;
+		}
+
+		// Store backlinks in the database
+		for (const refTid of referencedTopics) {
+			// Don't create self-references
+			if (refTid === tid) {
+				continue;
+			}
+
+			// Check if the referenced topic exists
+			const topicExists = await topics.exists(refTid);
+			if (!topicExists) {
+				continue;
+			}
+
+			// Store the backlink
+			await db.setAdd(`topic:${refTid}:backlinks`, pid);
+			await db.setObject(`backlink:${refTid}:${pid}`, {
+				pid: pid,
+				tid: tid,
+				uid: uid,
+				timestamp: Date.now(),
+			});
+
+			// Log a backlink event to the topic
+			await topics.events.log(refTid, {
+				type: 'backlink',
+				pid: pid,
+				tid: tid,
+				uid: uid,
+			});
+		}
+	};
+
+	/**
+	 * Update backlinks when a post is edited
+	 * @param {number} pid - Post ID
+	 * @param {string} oldContent - Old post content
+	 * @param {string} newContent - New post content
+	 * @param {number} tid - Topic ID
+	 * @param {number} uid - User ID
+	 */
+	Posts.updateBacklinks = async function (pid, oldContent, newContent, tid, uid) {
+		// Check if feature is enabled
+		if (!meta.config.enableTopicBacklinks) {
+			return;
+		}
+
+		const oldReferences = Posts.extractTopicReferences(oldContent);
+		const newReferences = Posts.extractTopicReferences(newContent);
+
+		// Find removed references
+		const removedReferences = oldReferences.filter(topicId => !newReferences.includes(topicId));
+		// Find added references
+		const addedReferences = newReferences.filter(topicId => !oldReferences.includes(topicId));
+
+		// Remove old backlinks
+		for (const refTid of removedReferences) {
+			if (refTid === tid) {
+				continue;
+			}
+
+			await db.setRemove(`topic:${refTid}:backlinks`, pid);
+			await db.deleteObject(`backlink:${refTid}:${pid}`);
+
+			// Remove backlink event from topic
+			const eventIds = await db.getSortedSetRange(`topic:${refTid}:events`, 0, -1);
+			const events = await db.getObjects(eventIds.map(id => `topicEvent:${id}`));
+
+			for (let i = 0; i < events.length; i++) {
+				if (events[i] && events[i].type === 'backlink' && events[i].pid === pid) {
+					await db.sortedSetRemove(`topic:${refTid}:events`, eventIds[i]);
+					await db.deleteObject(`topicEvent:${eventIds[i]}`);
+				}
+			}
+		}
+
+		// Add new backlinks
+		if (addedReferences.length) {
+			const postData = { pid, tid, uid, content: newContent };
+			await Posts.createBacklinks(postData);
+		}
+	};
+
+	/**
+	 * Remove all backlinks for a post
+	 * @param {number} pid - Post ID
+	 */
+	Posts.removeBacklinks = async function (pid) {
+		// Check if feature is enabled
+		if (!meta.config.enableTopicBacklinks) {
+			return;
+		}
+
+		// Get all topic IDs to search for backlinks
+		const tids = await db.getSortedSetRange('topics:tid', 0, -1);
+		if (!tids || !tids.length) {
+			return;
+		}
+
+		// Search through all topics to find backlinks
+		for (const tid of tids) {
+			const hasBacklink = await db.isSetMember(`topic:${tid}:backlinks`, pid);
+			if (hasBacklink) {
+				await db.setRemove(`topic:${tid}:backlinks`, pid);
+				await db.deleteObject(`backlink:${tid}:${pid}`);
+
+				// Remove backlink event from topic
+				const eventIds = await db.getSortedSetRange(`topic:${tid}:events`, 0, -1);
+				const events = await db.getObjects(eventIds.map(id => `topicEvent:${id}`));
+
+				for (let i = 0; i < events.length; i++) {
+					if (events[i] && events[i].type === 'backlink' && events[i].pid === pid) {
+						await db.sortedSetRemove(`topic:${tid}:events`, eventIds[i]);
+						await db.deleteObject(`topicEvent:${eventIds[i]}`);
+					}
+				}
+			}
+		}
+	};
+
+	/**
+	 * Get all backlinks for a topic
+	 * @param {number} tid - Topic ID
+	 * @returns {array} Array of post data
+	 */
+	Posts.getBacklinks = async function (tid) {
+		// Check if feature is enabled
+		if (!meta.config.enableTopicBacklinks) {
+			return [];
+		}
+
+		const pids = await db.getSetMembers(`topic:${tid}:backlinks`);
+		if (!pids || !pids.length) {
+			return [];
+		}
+
+		return await Posts.getPostsFields(pids, ['pid', 'tid', 'uid', 'timestamp', 'content']);
+	};
+};

