+/**
+ * Retrieves email for a user from multiple sources
+ * Tries: user object email field -> email history -> email:uid mapping
+ */
+UserEmail.getEmailForUid = async function (uid) {
+	// First try the main email field
+	let email = await user.getUserField(uid, 'email');
+	if (email) {
+		return email;
+	}
+
+	// Try to get from email history (stored when user was created or email changed)
+	const emailHistory = await db.getSortedSetRevRange(`user:${uid}:emails`, 0, 0);
+	if (emailHistory && emailHistory.length > 0) {
+		// Extract email from stored format "email:timestamp"
+		const parts = emailHistory[0].split(':');
+		if (parts.length > 0) {
+			email = parts[0];
+			if (email) {
+				return email;
+			}
+		}
+	}
+
+	// Try to find email from email:uid reverse lookup
+	const emailsByUid = await db.getSortedSetRange('email:uid', 0, -1);
+	for (const storedEmail of emailsByUid) {
+		const storedUid = await db.sortedSetScore('email:uid', storedEmail);
+		if (parseInt(storedUid, 10) === parseInt(uid, 10)) {
+			return storedEmail;
+		}
+	}
+
+	return null;
+};
+
+/**
+ * Gets email validation status for a user
+ * Returns: 'validated', 'pending', 'expired', or 'missing'
+ */
+UserEmail.getEmailStatus = async function (uid) {
+	const email = await UserEmail.getEmailForUid(uid);
+	if (!email) {
+		return 'missing';
+	}
+
+	const confirmed = await user.getUserField(uid, 'email:confirmed');
+	if (parseInt(confirmed, 10) === 1) {
+		return 'validated';
+	}
+
+	// Check if there's an active confirmation key
+	const confirmKey = await db.getSortedSetRange('confirm:uid', 0, -1);
+	let hasActiveKey = false;
+	for (const key of confirmKey) {
+		const confirmObj = await db.getObject(`confirm:${key}`);
+		if (confirmObj && parseInt(confirmObj.uid, 10) === parseInt(uid, 10)) {
+			// Check TTL to see if expired
+			const ttl = await db.pttl(`confirm:${key}`);
+			if (ttl > 0) {
+				hasActiveKey = true;
+				break;
+			}
+		}
+	}
+
+	if (hasActiveKey) {
+		return 'pending';
+	}
+
+	return 'expired';
+};
